from collections import deque

def solve(grid):
 h,w=len(grid),len(grid[0]); colors={v for row in grid for v in row if v not in (0,)}
 # background is most frequent non-marker presumably
 from collections import Counter
 bg=Counter(v for row in grid for v in row).most_common(1)[0][0]
 marks=[v for v in Counter(v for row in grid for v in row) if v!=bg]
 marker=next((v for v in marks if v!=0), None)
 # Marker may be a nonzero color distinct from bg
 if marker is None: return grid
 seen=set(); comps=[]
 for r in range(h):
  for c in range(w):
   if grid[r][c]==0 and (r,c) not in seen:
    q=[(r,c)];seen.add((r,c)); comp=[]
    for x,y in q:
     comp.append((x,y))
     for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
      nx,ny=x+dx,y+dy
      if 0<=nx<h and 0<=ny<w and grid[nx][ny]==0 and (nx,ny) not in seen:
       seen.add((nx,ny));q.append((nx,ny))
    comps.append(comp)
 threshold=sum(v==marker for row in grid for v in row)
 out=[row[:] for row in grid]
 for comp in comps:
  if len(comp)>=threshold:
   for r,c in comp: out[r][c]=marker
 return out

