def components(grid, color, conn8=False):
 h,w=len(grid),len(grid[0]); seen=set(); result=[]
 dirs=[(dr,dc) for dr in (-1,0,1) for dc in (-1,0,1) if dr or dc] if conn8 else [(1,0),(-1,0),(0,1),(0,-1)]
 for r in range(h):
  for c in range(w):
   if grid[r][c]==color and (r,c) not in seen:
    q=[(r,c)]; seen.add((r,c)); comp=[]
    for x,y in q:
     comp.append((x,y))
     for dr,dc in dirs:
      a,b=x+dr,y+dc
      if 0<=a<h and 0<=b<w and grid[a][b]==color and (a,b) not in seen: seen.add((a,b));q.append((a,b))
    result.append(comp)
 return result

def norm_shape(points):
 mr=min(x for x,y in points); mc=min(y for x,y in points)
 return frozenset((x-mr,y-mc) for x,y in points)
def transforms(shape):
 out=set()
 for flip in (1,-1):
  for k in range(4):
   ps=[]
   for r,c in shape:
    if flip==-1:c=-c
    for _ in range(k):r,c=c,-r
    ps.append((r,c))
   out.add(norm_shape(ps))
 return out

def stencil(grid, marker, outputcolor, allow_orient=True):
 h,w=len(grid),len(grid[0]); comp=max(components(grid,marker,True),key=len)
 sh=norm_shape(comp); variants=transforms(sh) if allow_orient else {sh}
 cells=set()
 for v in variants:
  H=max(r for r,c in v)+1; W=max(c for r,c in v)+1
  for r in range(h-H+1):
   for c in range(w-W+1):
    coords={(r+a,c+b) for a,b in v}
    if all(grid[x][y]==0 for x,y in coords):cells |= coords
 out=[row[:] for row in grid]
 for r,c in cells:out[r][c]=outputcolor
 return out,sh,cells

